-- Employee lifecycle: estimates do not reserve budget or post payroll/expenses.
CREATE TABLE el_roles(user_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('hiring_approver','review_moderator','access_officer')),PRIMARY KEY(user_id,role));
CREATE TABLE el_policies(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,rules TEXT NOT NULL,reason TEXT NOT NULL,actor_id INTEGER REFERENCES users(id));
INSERT INTO el_policies(kind,rules,reason) VALUES('staffing','[["hiring"]]','Configure independent hiring approval before organizational rollout'),('offer','[["hiring"]]','Independent hiring approval'),('training','[["hiring"]]','Independent training approval'),('change','[["hiring"]]','Independent employment change approval'),('departure','[["hiring"]]','Independent departure approval'),('final_policy','[["hiring"]]','Independent final-pay policy approval');
CREATE TABLE el_documents(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,date TEXT NOT NULL,employee_id INTEGER REFERENCES employees(id),creator_id INTEGER NOT NULL REFERENCES users(id),approval_policy TEXT NOT NULL,payload_encrypted TEXT NOT NULL,previous_id INTEGER REFERENCES el_documents(id),root_id INTEGER REFERENCES el_documents(id));
CREATE TABLE el_events(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES el_documents(id),kind TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),date TEXT NOT NULL,payload_encrypted TEXT NOT NULL);
CREATE TABLE el_budget_reviews(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES el_documents(id),actor_id INTEGER NOT NULL REFERENCES users(id),snapshot TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE el_vacancies(id INTEGER PRIMARY KEY,staffing_id INTEGER NOT NULL UNIQUE REFERENCES el_documents(id),reference TEXT NOT NULL UNIQUE,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_candidates(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,email_hash TEXT NOT NULL UNIQUE,user_id INTEGER REFERENCES users(id),payload_encrypted TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_applications(id INTEGER PRIMARY KEY,vacancy_id INTEGER NOT NULL REFERENCES el_vacancies(id),candidate_id INTEGER NOT NULL REFERENCES el_candidates(id),creator_id INTEGER NOT NULL REFERENCES users(id),UNIQUE(vacancy_id,candidate_id));
CREATE TABLE el_interviews(id INTEGER PRIMARY KEY,application_id INTEGER NOT NULL REFERENCES el_applications(id),panel_id INTEGER NOT NULL REFERENCES users(id),criteria TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,location TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_interview_cancellations(interview_id INTEGER PRIMARY KEY REFERENCES el_interviews(id),actor_id INTEGER NOT NULL REFERENCES users(id),reason TEXT NOT NULL);
CREATE TABLE el_scores(id INTEGER PRIMARY KEY,interview_id INTEGER NOT NULL UNIQUE REFERENCES el_interviews(id),payload_encrypted TEXT NOT NULL,score INTEGER NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_hiring_decisions(id INTEGER PRIMARY KEY,application_id INTEGER NOT NULL REFERENCES el_applications(id),decision TEXT NOT NULL CHECK(decision IN('selected','rejected','hold')),payload_encrypted TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_offer_links(document_id INTEGER PRIMARY KEY REFERENCES el_documents(id),application_id INTEGER NOT NULL REFERENCES el_applications(id),staffing_id INTEGER NOT NULL REFERENCES el_documents(id));
CREATE TABLE el_conversions(candidate_id INTEGER PRIMARY KEY REFERENCES el_candidates(id),offer_id INTEGER NOT NULL UNIQUE REFERENCES el_documents(id),employee_id INTEGER NOT NULL UNIQUE REFERENCES employees(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_templates(id INTEGER PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('onboarding','departure')),name TEXT NOT NULL,items TEXT NOT NULL,previous_id INTEGER REFERENCES el_templates(id),creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_cases(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),template_id INTEGER NOT NULL REFERENCES el_templates(id),document_id INTEGER REFERENCES el_documents(id),start_date TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_tasks(id INTEGER PRIMARY KEY,case_id INTEGER NOT NULL REFERENCES el_cases(id),title TEXT NOT NULL,kind TEXT NOT NULL,owner_id INTEGER NOT NULL REFERENCES users(id),reviewer_id INTEGER REFERENCES users(id),due_date TEXT NOT NULL,requires_review INTEGER NOT NULL CHECK(requires_review IN(0,1)));
CREATE TABLE el_task_events(id INTEGER PRIMARY KEY,task_id INTEGER NOT NULL REFERENCES el_tasks(id),kind TEXT NOT NULL CHECK(kind IN('submitted','completed','reopened')),payload_encrypted TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_probations(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),due_date TEXT NOT NULL,supervisor_id INTEGER NOT NULL REFERENCES users(id),creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_probation_reviews(id INTEGER PRIMARY KEY,probation_id INTEGER NOT NULL REFERENCES el_probations(id),outcome TEXT NOT NULL CHECK(outcome IN('confirm','extend','followup')),new_due_date TEXT,payload_encrypted TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_probation_approvals(review_id INTEGER PRIMARY KEY REFERENCES el_probation_reviews(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_equipment(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),reference TEXT NOT NULL UNIQUE,description TEXT NOT NULL,date TEXT NOT NULL,asset_id INTEGER REFERENCES acc_assets(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_equipment_returns(equipment_id INTEGER PRIMARY KEY REFERENCES el_equipment(id),date TEXT NOT NULL,reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_access_requests(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),kind TEXT NOT NULL CHECK(kind IN('local','external')),system TEXT NOT NULL,effective_date TEXT NOT NULL,roles TEXT NOT NULL,reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_access_approvals(request_id INTEGER PRIMARY KEY REFERENCES el_access_requests(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_access_applied(request_id INTEGER PRIMARY KEY REFERENCES el_access_requests(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_access_revocations(employee_id INTEGER PRIMARY KEY REFERENCES employees(id),departure_id INTEGER NOT NULL REFERENCES el_documents(id),date TEXT NOT NULL,user_id INTEGER REFERENCES users(id));
CREATE TABLE el_review_cycles(id INTEGER PRIMARY KEY,name TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,due_date TEXT NOT NULL,min_rating INTEGER NOT NULL,max_rating INTEGER NOT NULL,criteria TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_reviews(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),cycle_id INTEGER NOT NULL REFERENCES el_review_cycles(id),supervisor_id INTEGER NOT NULL REFERENCES users(id),goals TEXT NOT NULL,previous_id INTEGER REFERENCES el_reviews(id),creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_review_events(id INTEGER PRIMARY KEY,review_id INTEGER NOT NULL REFERENCES el_reviews(id),kind TEXT NOT NULL CHECK(kind IN('self','supervisor','moderation','finalize','acknowledgment','followup')),score INTEGER,payload_encrypted TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE UNIQUE INDEX el_review_final_once ON el_review_events(review_id) WHERE kind='finalize';
CREATE UNIQUE INDEX el_review_ack_once ON el_review_events(review_id) WHERE kind='acknowledgment';
CREATE TABLE el_training_links(document_id INTEGER PRIMARY KEY REFERENCES el_documents(id),request_id INTEGER NOT NULL UNIQUE REFERENCES requests(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_training_attendance(document_id INTEGER NOT NULL REFERENCES el_documents(id),employee_id INTEGER NOT NULL REFERENCES employees(id),attended INTEGER NOT NULL CHECK(attended IN(0,1)),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(document_id,employee_id));
CREATE TABLE el_qualifications(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),name TEXT NOT NULL,issuer TEXT NOT NULL,level TEXT NOT NULL,earned_date TEXT NOT NULL,expiry TEXT,training_id INTEGER REFERENCES el_documents(id),file_id INTEGER,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_self_requests(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),kind TEXT NOT NULL CHECK(kind IN('personal','payment','document')),effective_date TEXT NOT NULL,payload_encrypted TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_self_decisions(request_id INTEGER PRIMARY KEY REFERENCES el_self_requests(id),decision TEXT NOT NULL CHECK(decision IN('approved','rejected')),reason TEXT NOT NULL,result_kind TEXT,result_id INTEGER,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_change_links(document_id INTEGER PRIMARY KEY REFERENCES el_documents(id),term_id INTEGER REFERENCES employee_terms(id),profile_id INTEGER REFERENCES hr_profiles(id));
CREATE TABLE el_departure_links(document_id INTEGER PRIMARY KEY REFERENCES el_documents(id),case_id INTEGER REFERENCES el_cases(id),profile_id INTEGER REFERENCES hr_profiles(id));
CREATE TABLE el_final_requests(id INTEGER PRIMARY KEY,departure_id INTEGER NOT NULL REFERENCES el_documents(id),policy_id INTEGER NOT NULL REFERENCES el_documents(id),period_id INTEGER NOT NULL REFERENCES hr_periods(id),payload_encrypted TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_final_runs(request_id INTEGER PRIMARY KEY REFERENCES el_final_requests(id),run_id INTEGER NOT NULL UNIQUE REFERENCES payroll_runs(id));
CREATE TABLE el_departure_closures(document_id INTEGER PRIMARY KEY REFERENCES el_documents(id),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_files(id INTEGER PRIMARY KEY,owner_kind TEXT NOT NULL,owner_id INTEGER NOT NULL,filename TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN('shared','private')),content_encrypted TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_retention_policies(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,retention_days INTEGER NOT NULL CHECK(retention_days>=1),legal_hold INTEGER NOT NULL CHECK(legal_hold IN(0,1)),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));

CREATE TABLE el_change_proposals(document_id INTEGER PRIMARY KEY REFERENCES el_documents(id),term_id INTEGER NOT NULL UNIQUE REFERENCES employee_terms(id));
CREATE TABLE el_departure_advances(document_id INTEGER NOT NULL REFERENCES el_documents(id),advance_id INTEGER NOT NULL UNIQUE REFERENCES advances(id),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(document_id,advance_id));

CREATE TABLE el_departure_liabilities(document_id INTEGER NOT NULL REFERENCES el_documents(id),expense_id INTEGER NOT NULL UNIQUE REFERENCES expenses(id),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(document_id,expense_id));
CREATE TABLE el_final_reviews(id INTEGER PRIMARY KEY,departure_id INTEGER NOT NULL REFERENCES el_documents(id),policy_id INTEGER NOT NULL REFERENCES el_documents(id),run_id INTEGER NOT NULL REFERENCES payroll_runs(id),reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE el_final_review_approvals(review_id INTEGER PRIMARY KEY REFERENCES el_final_reviews(id),actor_id INTEGER NOT NULL REFERENCES users(id));
